10	export interface Card {
11	  monster: Monster;
12	  rank?: 1 | 2 | 3;
13	}
14	
15	const VARIETY_THRESHOLD = 3;
16	const POINTS_PER_SPHINX_BEYOND_THRESHOLD = 2;
17	const POINTS_PER_SPHINX = 1;
18	
19	const isSphinx = (card: Card): boolean => card.monster === "sphinx";
20	
21	const countDistinctMonsterTypes = (army: Card[]): number =>
22	  new Set(army.map((card) => card.monster)).size;
23	
24	const pointsPerSphinx = (army: Card[]): number =>
25	  countDistinctMonsterTypes(army) > VARIETY_THRESHOLD
26	    ? POINTS_PER_SPHINX_BEYOND_THRESHOLD
27	    : POINTS_PER_SPHINX;
28	
29	export const scoreArmy = (army: Card[]): number =>
30	  army.filter(isSphinx).length * pointsPerSphinx(army);
31

1	import { describe, it, expect } from "vitest";
2	import { scoreArmy } from "./sphinx-score.js";
3	
4	describe("Sphinx scoring", () => {
5	  // Simplest cases — no Sphinx, no points
6	  it("scores an empty army as 0", () => {
7	    expect(scoreArmy([])).toBe(0);
8	  });
