14	      scoreArmy([
15	        { monster: "hydra" },
16	        { monster: "zombie" },
17	        { monster: "cyclops" },
18	        { monster: "orthrus" },
19	      ]),
20	    ).toBe(0);
21	  });
22	
23	  // A single Sphinx, three or fewer types — 1 point each
